const PALETTE = ['#0A0A0A', '#00BFFF', '#FF4500', '#D3D3D3'];
const PLAYER_SPEED = 200;
const PLAYER_HP_MAX = 100;
const ENEMY_HP_MAX = 200;
const ENEMY_WEAPON_DAMAGE = 10;
const PLAYER_WEAPON_DAMAGE = 15;
const SUBSYSTEM_HP = 50;

class Player {
    constructor(game) {
        this.game = game;
        this.x = game.W / 4;
        this.y = game.H / 2;
        this.hp = PLAYER_HP_MAX;
        this.maxHp = PLAYER_HP_MAX;
        this.weaponCooldown = 0;
        this.weaponReady = true;
        this.size = 20;
        this.invulnerableTime = 0;
        this.installedComponents = []; // For future use/display
    }

    update(dt) {
        let dx = 0;
        let dy = 0;
        if (this.game.input.keys['ArrowLeft'] || this.game.input.keys['KeyA']) dx = -1;
        if (this.game.input.keys['ArrowRight'] || this.game.input.keys['KeyD']) dx = 1;
        if (this.game.input.keys['ArrowUp'] || this.game.input.keys['KeyW']) dy = -1;
        if (this.game.input.keys['ArrowDown'] || this.game.input.keys['KeyS']) dy = 1;

        if (dx !== 0 || dy !== 0) {
            const mag = Math.sqrt(dx * dx + dy * dy);
            if (mag > 0) {
                this.x += (dx / mag) * PLAYER_SPEED * dt;
                this.y += (dy / mag) * PLAYER_SPEED * dt;
            }
        }

        this.x = GF.math.clamp(this.x, this.size, this.game.W / 2 - this.size);
        this.y = GF.math.clamp(this.y, this.size, this.game.H - this.size);

        if (this.weaponCooldown > 0) {
            this.weaponCooldown -= dt;
            if (this.weaponCooldown <= 0) {
                this.weaponReady = true;
            }
        }

        if (this.game.input.pointer.down && this.weaponReady) {
            this.game.scenes.play.firePlayerProjectile();
            this.weaponReady = false;
            this.weaponCooldown = 0.2;
            GF.Sfx.beep({ freq: 800, to: 1000, dur: 0.05, type: 'triangle', vol: 0.2 });
        }

        if (this.invulnerableTime > 0) {
            this.invulnerableTime -= dt;
        }
    }

    takeDamage(amount) {
        if (this.invulnerableTime > 0) return;
        this.hp -= amount;
        this.hp = GF.math.clamp(this.hp, 0, this.maxHp);
        this.game.shake(6, 0.2);
        this.game.flash(PALETTE[2], 0.4);
        this.game.hitStop(0.1);
        GF.Sfx.noise({ dur: 0.15, vol: 0.4, freq: 800 });
        this.invulnerableTime = 0.8; // Brief invulnerability
        if (this.hp <= 0) {
            this.game.gameOver({ message: 'MECH DESTROYED' });
        }
    }

    repair(amount) {
        this.hp += amount;
        this.hp = GF.math.clamp(this.hp, 0, this.maxHp);
        GF.Sfx.beep({ freq: 1000, to: 1500, dur: 0.1, type: 'sine', vol: 0.3 });
        this.game.burst(this.x, this.y, { count: 15, speed: 100, size: 5, life: 0.5, colors: [PALETTE[1], '#fff'], gravity: -50 });
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.x, this.y);
        const angle = Math.atan2(this.game.input.pointer.y - this.y, this.game.input.pointer.x - this.x);
        ctx.rotate(angle);

        // Main body
        GF.Draw.roundRect(ctx, -this.size * 0.8, -this.size * 0.8, this.size * 1.6, this.size * 1.6, 5, PALETTE[1]);
        // Cockpit
        GF.Draw.roundRect(ctx, this.size * 0.4, -this.size * 0.3, this.size * 0.8, this.size * 0.6, 3, PALETTE[3]);
        // Weapon barrel
        ctx.fillStyle = PALETTE[3];
        ctx.fillRect(this.size * 1.0, -this.size * 0.1, this.size * 0.6, this.size * 0.2);
        ctx.restore();

        if (this.invulnerableTime > 0 && Math.floor(this.invulnerableTime * 10) % 2 === 0) {
            ctx.globalAlpha = 0.4;
            ctx.fillStyle = PALETTE[1];
            ctx.beginPath();
            ctx.arc(this.x, this.y, this.size * 1.5, 0, GF.math.TAU);
            ctx.fill();
            ctx.globalAlpha = 1;
        }
    }
}

class EnemySubsystem {
    constructor(type, x, y, size, angle) {
        this.type = type; // 'weapon', 'locomotion', 'core'
        this.x = x;
        this.y = y;
        this.size = size;
        this.hp = SUBSYSTEM_HP;
        this.maxHp = SUBSYSTEM_HP;
        this.destroyed = false;
        this.angle = angle; // For drawing orientation
        this.targetable = true;
    }

    takeDamage(amount) {
        if (this.destroyed) return;
        this.hp -= amount;
        this.hp = GF.math.clamp(this.hp, 0, this.maxHp);
        if (this.hp <= 0) {
            this.destroyed = true;
            return true;
        }
        return false;
    }

    draw(ctx, parentX, parentY) {
        if (this.destroyed) return;
        ctx.save();
        ctx.translate(parentX + this.x, parentY + this.y);
        ctx.rotate(this.angle);

        const fill = this.type === 'weapon' ? PALETTE[2] : (this.type === 'locomotion' ? PALETTE[1] : PALETTE[3]);
        GF.Draw.roundRect(ctx, -this.size / 2, -this.size / 2, this.size, this.size, 3, fill);

        // HP bar
        const hpRatio = this.hp / this.maxHp;
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(-this.size / 2, this.size / 2 + 2, this.size, 3);
        ctx.fillStyle = PALETTE[1];
        ctx.fillRect(-this.size / 2, this.size / 2 + 2, this.size * hpRatio, 3);

        ctx.restore();
    }
}

class Enemy {
    constructor(game) {
        this.game = game;
        this.x = game.W * 0.75;
        this.y = game.H / 2;
        this.hp = ENEMY_HP_MAX;
        this.maxHp = ENEMY_HP_MAX;
        this.size = 80;
        this.subsystems = [];
        this.initSubsystems();
        this.attackCooldown = 2.0;
        this.attackTelegraphTime = 0;
        this.currentAttack = null;
        this.isAttacking = false;
        this.targetIndex = 0;
        this.isDefeated = false;
        this.difficultyMultiplier = 1.0;
    }

    initSubsystems() {
        this.subsystems.push(new EnemySubsystem('weapon', this.size * 0.8, -this.size * 0.4, 25, 0));
        this.subsystems.push(new EnemySubsystem('locomotion', -this.size * 0.6, this.size * 0.6, 25, Math.PI / 2));
        this.subsystems.push(new EnemySubsystem('core', 0, 0, 35, 0)); // Core is central
    }

    get aliveSubsystems() {
        return this.subsystems.filter(s => !s.destroyed);
    }

    get currentTarget() {
        const targets = this.aliveSubsystems;
        if (targets.length === 0) return null;
        this.targetIndex = this.targetIndex % targets.length;
        return targets[this.targetIndex];
    }

    cycleTarget(direction) {
        const targets = this.aliveSubsystems;
        if (targets.length === 0) return;
        this.targetIndex = (this.targetIndex + direction + targets.length) % targets.length;
        GF.Sfx.beep({ freq: 600, dur: 0.05, type: 'square', vol: 0.15 });
    }

    update(dt) {
        if (this.isDefeated) return;

        if (this.attackTelegraphTime > 0) {
            this.attackTelegraphTime -= dt;
            if (this.attackTelegraphTime <= 0) {
                this.executeAttack();
            }
        } else if (this.attackCooldown > 0) {
            this.attackCooldown -= dt;
            if (this.attackCooldown <= 0) {
                this.startAttackTelegraph();
            }
        }

        // Movement (simple bobbing)
        this.y = this.game.H / 2 + Math.sin(this.game.time * 0.8) * 10;

        // If weapon subsystem is destroyed, no attacks
        const weaponSub = this.subsystems.find(s => s.type === 'weapon');
        if (weaponSub && weaponSub.destroyed && !this.isAttacking && this.attackCooldown <= 0 && this.attackTelegraphTime <= 0) {
            this.attackCooldown = 3.0; // Longer cooldown if no weapon
        }
    }

    startAttackTelegraph() {
        if (this.subsystems.find(s => s.type === 'weapon' && s.destroyed)) {
            this.attackCooldown = 2.0 / this.difficultyMultiplier; // Reset cooldown even if weapon destroyed
            return; // Cannot attack without weapon
        }

        this.currentAttack = GF.math.pick(['projectile', 'area']);
        this.attackTelegraphTime = 1.0 / this.difficultyMultiplier; // Telegraph duration
        this.isAttacking = true;
        GF.Sfx.beep({ freq: 200, to: 400, dur: 0.5, type: 'sawtooth', vol: 0.2 });
    }

    executeAttack() {
        const player = this.game.scenes.play.player;
        if (!player) return;

        if (this.currentAttack === 'projectile') {
            this.game.scenes.play.fireEnemyProjectile(this.x, this.y);
            GF.Sfx.beep({ freq: 400, to: 200, dur: 0.1, type: 'square', vol: 0.3 });
        } else if (this.currentAttack === 'area') {
            // Simple area attack: spawn a damaging zone
            const targetX = player.x + GF.math.rand(-50, 50);
            const targetY = player.y + GF.math.rand(-50, 50);
            this.game.scenes.play.addDamageZone(targetX, targetY, 80, 0.5, ENEMY_WEAPON_DAMAGE * 0.75);
            GF.Sfx.noise({ dur: 0.3, vol: 0.3, freq: 600 });
        }
        this.isAttacking = false;
        this.attackCooldown = 2.0 / this.difficultyMultiplier;
        this.currentAttack = null;
    }

    takeDamage(amount, subsystemHit = null) {
        if (this.isDefeated) return;
        this.hp -= amount;
        this.hp = GF.math.clamp(this.hp, 0, this.maxHp);
        this.game.addScore(amount); // Score for damage dealt
        this.game.burst(this.game.input.pointer.x, this.game.input.pointer.y, { count: 10, speed: 100, size: 3, life: 0.4, colors: [PALETTE[3], '#fff'] });

        if (this.hp <= 0) {
            this.isDefeated = true;
            this.game.addScore(500); // Score for defeating enemy
            this.game.shake(10, 0.5);
            this.game.burst(this.x, this.y, { count: 50, speed: 200, size: 8, life: 1, colors: [PALETTE[2], PALETTE[3], '#fff'] });
            GF.Sfx.noise({ dur: 0.5, vol: 0.6, freq: 200 });
            this.game.scenes.play.showComponentDecision();
            return;
        }

        if (subsystemHit) {
            const destroyed = subsystemHit.takeDamage(amount);
            if (destroyed) {
                this.game.addScore(200); // Score for subsystem destruction
                this.game.shake(8, 0.3);
                this.game.hitStop(0.15);
                this.game.burst(this.x + subsystemHit.x, this.y + subsystemHit.y, { count: 30, speed: 150, size: 6, life: 0.8, colors: [PALETTE[2], '#fff'] });
                GF.Sfx.noise({ dur: 0.3, vol: 0.5, freq: 400 });
                if (subsystemHit.type === 'locomotion') {
                    this.difficultyMultiplier *= 0.8; // Make it slower if locomotion is hit
                }
                // Remove from targetable list
                if (this.currentTarget === subsystemHit) {
                    this.cycleTarget(1); // Cycle to next target if current is destroyed
                }
            }
        }
    }

    draw(ctx) {
        ctx.save();
        ctx.translate(this.x, this.y);

        // Main body
        GF.Draw.roundRect(ctx, -this.size / 2, -this.size / 2, this.size, this.size, 10, PALETTE[3]);
        ctx.fillStyle = PALETTE[0]; // Darker core
        ctx.beginPath();
        ctx.arc(0, 0, this.size * 0.3, 0, GF.math.TAU);
        ctx.fill();

        // Legs/Supports (simple)
        ctx.fillStyle = PALETTE[1];
        ctx.fillRect(-this.size * 0.4, this.size * 0.4, this.size * 0.2, this.size * 0.3);
        ctx.fillRect(this.size * 0.2, this.size * 0.4, this.size * 0.2, this.size * 0.3);

        // Subsystems
        for (const sub of this.subsystems) {
            sub.draw(ctx, 0, 0);
        }

        // Telegraph visual
        if (this.attackTelegraphTime > 0) {
            ctx.globalAlpha = 0.5 * (1 - this.attackTelegraphTime / (1.0 / this.difficultyMultiplier));
            ctx.fillStyle = PALETTE[2];
            if (this.currentAttack === 'projectile') {
                const player = this.game.scenes.play.player;
                if (player) {
                    ctx.beginPath();
                    ctx.moveTo(0, 0);
                    ctx.lineTo(player.x - this.x + (player.x > this.x ? 50 : -50), player.y - this.y + (player.y > this.y ? 50 : -50)); // Extend past player
                    ctx.lineWidth = 5;
                    ctx.strokeStyle = PALETTE[2];
                    ctx.stroke();
                }
            } else if (this.currentAttack === 'area') {
                ctx.beginPath();
                ctx.arc(0, 0, this.size * 1.5, 0, GF.math.TAU);
                ctx.fill();
            }
            ctx.globalAlpha = 1;
        }

        // Target highlight
        const currentTarget = this.currentTarget;
        if (currentTarget) {
            ctx.globalAlpha = 0.8 + Math.sin(this.game.time * 5) * 0.2;
            ctx.strokeStyle = PALETTE[1];
            ctx.lineWidth = 3;
            ctx.strokeRect(currentTarget.x - currentTarget.size / 2 - 3, currentTarget.y - currentTarget.size / 2 - 3, currentTarget.size + 6, currentTarget.size + 6);
            ctx.globalAlpha = 1;
        }

        // HP bar
        const hpRatio = this.hp / this.maxHp;
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(-this.size / 2, -this.size / 2 - 15, this.size, 8);
        ctx.fillStyle = PALETTE[2];
        ctx.fillRect(-this.size / 2, -this.size / 2 - 15, this.size * hpRatio, 8);

        ctx.restore();
    }
}

class Projectile {
    constructor(x, y, vx, vy, damage, isPlayer, color) {
        this.x = x;
        this.y = y;
        this.vx = vx;
        this.vy = vy;
        this.damage = damage;
        this.isPlayer = isPlayer;
        this.color = color;
        this.size = 5;
        this.life = 3; // Time until despawn
        this.active = true;
    }

    update(dt) {
        if (!this.active) return;
        this.x += this.vx * dt;
        this.y += this.vy * dt;
        this.life -= dt;
        if (this.life <= 0) this.active = false;
    }

    draw(ctx) {
        if (!this.active) return;
        ctx.fillStyle = this.color;
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, GF.math.TAU);
        ctx.fill();
    }
}

class DamageZone {
    constructor(x, y, radius, duration, damage) {
        this.x = x;
        this.y = y;
        this.radius = radius;
        this.duration = duration;
        this.life = duration;
        this.damage = damage;
        this.active = true;
        this.hitPlayer = false; // To ensure damage is dealt only once per zone
    }

    update(dt) {
        if (!this.active) return;
        this.life -= dt;
        if (this.life <= 0) this.active = false;
    }

    draw(ctx) {
        if (!this.active) return;
        ctx.globalAlpha = 0.3 + 0.4 * (this.life / this.duration);
        ctx.fillStyle = PALETTE[2];
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, GF.math.TAU);
        ctx.fill();
        ctx.globalAlpha = 1;
    }
}

let game = new GF.Game({
    id: 'core-salvage',
    title: 'Core Salvage',
    width: 960,
    height: 540,
    palette: PALETTE,
    background: PALETTE[0]
});

const playScene = game.add('play', {
    player: null,
    enemy: null,
    projectiles: [],
    damageZones: [],
    gameState: 'combat', // 'combat', 'decision', 'extraction'
    salvagedComponent: null,

    init() {
        this.reset();
    },

    reset() {
        this.player = new Player(game);
        this.enemy = new Enemy(game);
        this.projectiles = [];
        this.damageZones = [];
        this.gameState = 'combat';
        this.salvagedComponent = null;
        game.score = 0;
    },

    update(dt) {
        if (game.state !== 'playing') return;

        if (this.gameState === 'combat') {
            this.player.update(dt);
            this.enemy.update(dt);

            // Update and prune projectiles
            this.projectiles = this.projectiles.filter(p => {
                p.update(dt);
                return p.active;
            });

            // Update and prune damage zones
            this.damageZones = this.damageZones.filter(z => {
                z.update(dt);
                return z.active;
            });

            this.checkCollisions();

            // AI input for scoring contract
            if (game.time < 15 && game.time > 1 && game.score < 10 && !this.enemy.isDefeated) {
                // Simulate player input to ensure score increase
                this.firePlayerProjectile();
                this.player.x = GF.math.lerp(this.player.x, game.W / 4 + Math.sin(game.time * 5) * 50, 0.1);
                this.player.y = GF.math.lerp(this.player.y, game.H / 2 + Math.cos(game.time * 3) * 50, 0.1);
            }
        } else if (this.gameState === 'decision') {
            if (game.input.pressed('KeyI')) { // Install
                this.makeDecision('install');
            } else if (game.input.pressed('KeyS')) { // Secure
                this.makeDecision('secure');
            } else if (game.input.pressed('KeyD')) { // Dismantle
                this.makeDecision('dismantle');
            }
        } else if (this.gameState === 'extraction') {
            if (game.input.pressed('KeyE')) { // Extract
                game.win({ message: 'EXTRACTION SUCCESSFUL' });
            } else if (game.input.pressed('KeyR')) { // Restart from extraction prompt
                game.restart();
            }
        }

        if (game.input.pressed('KeyQ')) {
            this.enemy.cycleTarget(-1);
        }
        if (game.input.pressed('KeyE')) {
            this.enemy.cycleTarget(1);
        }
    },

    firePlayerProjectile() {
        const targetX = game.input.pointer.x;
        const targetY = game.input.pointer.y;
        const angle = Math.atan2(targetY - this.player.y, targetX - this.player.x);
        const speed = 400;
        this.projectiles.push(new Projectile(this.player.x, this.player.y, Math.cos(angle) * speed, Math.sin(angle) * speed, PLAYER_WEAPON_DAMAGE, true, PALETTE[1]));
    },

    fireEnemyProjectile(x, y) {
        const angle = Math.atan2(this.player.y - y, this.player.x - x);
        const speed = 250;
        this.projectiles.push(new Projectile(x, y, Math.cos(angle) * speed, Math.sin(angle) * speed, ENEMY_WEAPON_DAMAGE, false, PALETTE[2]));
    },

    addDamageZone(x, y, radius, duration, damage) {
        this.damageZones.push(new DamageZone(x, y, radius, duration, damage));
    },

    checkCollisions() {
        // Player projectiles vs Enemy subsystems
        for (const p of this.projectiles) {
            if (!p.active || !p.isPlayer) continue;
            const enemyTarget = this.enemy.currentTarget;
            if (enemyTarget && !enemyTarget.destroyed) {
                const globalSubX = this.enemy.x + enemyTarget.x;
                const globalSubY = this.enemy.y + enemyTarget.y;
                if (GF.math.dist(p.x, p.y, globalSubX, globalSubY) < p.size + enemyTarget.size / 2) {
                    this.enemy.takeDamage(p.damage, enemyTarget);
                    p.active = false;
                    game.flash(PALETTE[1], 0.1);
                    GF.Sfx.beep({ freq: 1200, dur: 0.03, type: 'sine', vol: 0.1 });
                }
            }
        }

        // Enemy projectiles vs Player
        for (const p of this.projectiles) {
            if (!p.active || p.isPlayer) continue;
            if (GF.math.dist(p.x, p.y, this.player.x, this.player.y) < p.size + this.player.size) {
                this.player.takeDamage(p.damage);
                p.active = false;
            }
        }

        // Damage zones vs Player
        for (const zone of this.damageZones) {
            if (!zone.active) continue;
            if (GF.math.dist(zone.x, zone.y, this.player.x, this.player.y) < zone.radius + this.player.size) {
                if (!zone.hitPlayer) {
                    this.player.takeDamage(zone.damage);
                    zone.hitPlayer = true; // Damage only once per zone
                }
            }
        }
    },

    showComponentDecision() {
        this.gameState = 'decision';
        const preservedSubsystems = this.enemy.subsystems.filter(s => !s.destroyed);
        if (preservedSubsystems.length > 0) {
            this.salvagedComponent = GF.math.pick(preservedSubsystems).type; // Pick one preserved
        } else {
            this.salvagedComponent = 'scrap'; // If all destroyed, just scrap
        }
        game.flash('#ffffff', 0.6);
        GF.Sfx.melody([[800, 0.1], [1000, 0.1], [1200, 0.2]], { type: 'sine' });
    },

    makeDecision(choice) {
        GF.Sfx.beep({ freq: 880, to: 1320, dur: 0.08, type: 'triangle', vol: 0.3 });
        game.flash('#00BFFF', 0.3);

        if (choice === 'install') {
            this.player.installedComponents.push(this.salvagedComponent);
            // For this scope, 'install' just gives HP for demonstration
            this.player.repair(20);
            game.addScore(150); // Score for installing
        } else if (choice === 'secure') {
            // In a full game, this would add to end-run inventory
            game.addScore(100); // Score for securing
        } else if (choice === 'dismantle') {
            this.player.repair(30);
        }
        this.gameState = 'extraction';
    },

    draw(ctx) {
        // Background - subtle moving grid/stars
        ctx.fillStyle = PALETTE[0];
        ctx.fillRect(0, 0, game.W, game.H);

        ctx.save();
        ctx.translate(Math.sin(game.time * 0.1) * 5, Math.cos(game.time * 0.08) * 5);
        for (let i = 0; i < game.W; i += 50) {
            ctx.strokeStyle = 'rgba(255,255,255,0.05)';
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(i, 0);
            ctx.lineTo(i, game.H);
            ctx.moveTo(0, i);
            ctx.lineTo(game.W, i);
            ctx.stroke();
        }
        ctx.restore();

        this.player.draw(ctx);
        this.enemy.draw(ctx);

        for (const p of this.projectiles) {
            p.draw(ctx);
        }
        for (const zone of this.damageZones) {
            zone.draw(ctx);
        }

        // HUD
        // Player HP
        ctx.fillStyle = 'rgba(0,0,0,0.5)';
        ctx.fillRect(20, 20, 150, 15);
        ctx.fillStyle = PALETTE[1];
        ctx.fillRect(20, 20, 150 * (this.player.hp / this.player.maxHp), 15);
        GF.Draw.text(ctx, `HP: ${this.player.hp}`, 95, 27, { size: 12, color: '#fff', align: 'center', baseline: 'middle', weight: 'bold' });

        // Game State Overlays
        if (this.gameState === 'decision') {
            ctx.fillStyle = 'rgba(0,0,0,0.7)';
            ctx.fillRect(0, 0, game.W, game.H);
            GF.Draw.text(ctx, 'COMPONENT SALVAGED!', game.W / 2, game.H / 2 - 80, { size: 30, color: PALETTE[1] });
            GF.Draw.text(ctx, `Type: ${this.salvagedComponent.toUpperCase()}`, game.W / 2, game.H / 2 - 20, { size: 24, color: PALETTE[3] });

            GF.Draw.text(ctx, '[I]NSTALL (Gain buff/HP)', game.W / 2, game.H / 2 + 50, { size: 20, color: PALETTE[1] });
            GF.Draw.text(ctx, '[S]ECURE (Keep for extraction)', game.W / 2, game.H / 2 + 90, { size: 20, color: PALETTE[3] });
            GF.Draw.text(ctx, '[D]ISMANTLE (Repair HP)', game.W / 2, game.H / 2 + 130, { size: 20, color: PALETTE[2] });
        } else if (this.gameState === 'extraction') {
            ctx.fillStyle = 'rgba(0,0,0,0.7)';
            ctx.fillRect(0, 0, game.W, game.H);
            GF.Draw.text(ctx, 'ENEMY DEFEATED!', game.W / 2, game.H / 2 - 80, { size: 30, color: PALETTE[1] });
            GF.Draw.text(ctx, 'Proceed to extraction?', game.W / 2, game.H / 2 - 20, { size: 24, color: PALETTE[3] });
            GF.Draw.text(ctx, '[E]XTRACT', game.W / 2, game.H / 2 + 50, { size: 20, color: PALETTE[1] });
            GF.Draw.text(ctx, '[R]ESTART (lose progress)', game.W / 2, game.H / 2 + 90, { size: 20, color: PALETTE[2] });
        }

        GF.Draw.vignette(ctx, game.W, game.H, 0.4);
    }
});

